import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(t):
        try:
            x = int(next(iterator))
        except StopIteration:
            break

        if x == 0:
            results.append((1, 1))
            continue

        found = False
        for m in range(1, 1000000):
            if m * m > x:
                break

            # We need n*n - (n-m+1)^2 = x
            # Let k = n - m + 1, then n = k + m - 1
            # (k+m-1)^2 - k^2 = x
            # (k+m-1 - k)(k+m-1 + k) = x
            # (m-1)(2k + m - 1) = x

            if m == 1:
                # (0)(...) = 0, so x must be 0. But x > 0 here.
                # However, if m=1, max ones is n*n - (n)^2 = 0? 
                # Wait, definition: m-free means every m*m submatrix has a zero.
                # If m=1, every 1x1 submatrix has a zero => no 1s allowed. Max 1s = 0.
                # So if x > 0, m cannot be 1.
                continue

            diff = m - 1
            if x % diff != 0:
                continue

            term2 = x // diff
            # term2 = 2k + m - 1
            # 2k = term2 - m + 1
            # k = (term2 - m + 1) / 2

            num = term2 - m + 1
            if num < 0 or num % 2 != 0:
                continue

            k = num // 2
            if k < 1:
                continue

            n = k + m - 1

            # Check constraints
            if n > 10**9:
                continue

            # Verify
            val = n * n - (n - m + 1) * (n - m + 1)
            if val == x:
                results.append((n, m))
                found = True
                break

        if not found:
            results.append((-1, 0))

    for res in results:
        if res[0] == -1:
            print("-1")
        else:
            print(f"{res[0]} {res[1]}")

if __name__ == "__main__":
    solve()
